questionvariables.text:
g  : rand_with_prohib(1,2,[]);        /* equal time gap */
t1 : rand_with_prohib(1,2,[]);        /* first time */
t2 : t1 + g;
t3 : t1 + 2*g;
r1 : rand_with_prohib(3,12,[]);       /* average rate on [t1,t2] */
r2 : rand_with_prohib(3,12,[r1]);     /* average rate on [t2,t3], different */
d1 : rand_with_prohib(2,8,[]);        /* distance at t1 */
d2 : d1 + r1*g;
d3 : d2 + r2*g;
Apt : [t1, d1];
Bpt : [t2, d2];
Cpt : [t3, d3];
/* dropdown for part (c) */
lbl1 : sconcat("t = ", t1, " to t = ", t2);
lbl2 : sconcat("t = ", t2, " to t = ", t3);
copts : [[optI1, is(r1 > r2), lbl1], [optI2, is(r2 > r1), lbl2]];
ta_c  : if r1 > r2 then optI1 else optI2;
clabel : if r1 > r2 then lbl1 else lbl2;
rmax : max(r1, r2);
rmin : min(r1, r2);
/* board window (distance and time have different units, so no square scaling) */
xminv : min(t1, 0) - 1;
xmaxv : t3 + 1;
yminv : min(d1, 0) - 2;
ymaxv : d3 + 3;
dlo : t1 - 0.3;
dhi : t3 + 0.3;
tans1 : Apt;
tans2 : Bpt;
tans3 : Cpt;

feedbackvariables.text:
q1 : [round(ans3[1]), round(ans3[2])];
q2 : [round(ans4[1]), round(ans4[2])];
q3 : [round(ans5[1]), round(ans5[2])];
midok : if is(q2 = Bpt) then 1 else 0;
endok : if ((is(q1 = Apt) and is(q3 = Cpt)) or (is(q1 = Cpt) and is(q3 = Apt))) then 1 else 0;
allok : midok*endok;
